def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    rich_pressure = 0
    desperate_pressure = 0

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if bid >= 110:
                    rich_pressure += 1
                if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
                    desperate_pressure += 1

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if supply >= 23:
        scarcity = 0
    elif supply >= 20:
        scarcity = 1
    elif supply >= 17:
        scarcity = 2
    else:
        scarcity = 3

    emergency = hp <= 2 or no_water >= 2
    urgent = hp <= 4 or no_water >= 1

    if emergency:
        base = 0.92 * DAILY_SALARY
        if highest_prev > 0:
            base = max(base, min(highest_prev + 6.0, 0.98 * DAILY_SALARY))
        if scarcity >= 2:
            base += 4.0
        return float(min(budget, max(0.0, base)))

    if urgent:
        if scarcity >= 2:
            base = max(0.78 * DAILY_SALARY, min(highest_prev + 3.0, 0.9 * DAILY_SALARY))
        else:
            base = max(0.62 * DAILY_SALARY, min(avg_prev + 2.0, 0.82 * DAILY_SALARY))
        return float(min(budget, max(0.0, base)))

    if scarcity == 0:
        base = 18.0
    elif scarcity == 1:
        base = 26.0
    elif scarcity == 2:
        base = 34.0
    else:
        base = 42.0

    if highest_prev >= 130:
        base -= 8.0
    elif highest_prev >= 100:
        base -= 4.0
    elif highest_prev <= 60 and prev_bids:
        base += 6.0

    base += desperate_pressure * 2.5
    base -= rich_pressure * 2.0

    if day >= 8 and hp >= 6:
        base -= 4.0

    reserve_floor = DAILY_SALARY * max(0, 10 - int(day)) * 0.18
    cap = budget
    if budget > reserve_floor:
        cap = max(0.0, budget - reserve_floor * 0.15)

    bid = min(cap, base)
    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents and their yesterday bids
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Pressure-based target: if opponents were bidding high yesterday, we must match/beat to secure water.
    # Use our hp as survival pressure.
    hp = my_status['hp']
    budget = my_status['budget']

    # Estimate how many successful water units we might need from today's supply context.
    # (We only need to decide a bid; keep it simple and robust.)
    # If supply is low, competition likely increases -> bid more.
    supply_low = supply <= float((MIN_SUPPLY + MAX_SUPPLY) / 2.0)

    # Base aggressiveness
    if hp <= 2:
        base = DAILY_SALARY * 0.92
    elif hp <= 4:
        base = DAILY_SALARY * 0.70
    else:
        base = DAILY_SALARY * 0.55

    # If opponents pushed hard yesterday, increase to just above them when affordable.
    # Keep a small increment to win without excessive waste.
    if highest_prev_bid >= DAILY_SALARY * 0.80:
        target = max(base, highest_prev_bid + 2.0)
    else:
        target = base

    # If supply is low, add a bit more to secure allocation.
    if supply_low:
        target *= 1.08

    # Clamp by budget and keep within a reasonable fraction of daily salary.
    # Also prevent bidding beyond what would guarantee waste.
    upper_cap = min(budget, DAILY_SALARY * 1.25)
    bid = min(target, upper_cap)

    # Ensure bid is non-negative and not NaN.
    if bid != bid or bid < 0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
